W=/home/t3/rq-f52/2026-11-13-claude-builtin-fable-5-2-high/att-032/clone-work && mkdir -p $W && cat > $W/bench.js <<'EOF'
require(process.cwd() + '/resources/ts-register.js');
const { parse } = require(process.cwd() + '/src/language/parser');
const { buildSchema } = require(process.cwd() + '/src/utilities/buildASTSchema');
const { validate } = require(process.cwd() + '/src/validation/validate');
const { OverlappingFieldsCanBeMergedRule } = require(process.cwd() + '/src/validation/rules/OverlappingFieldsCanBeMergedRule');
const schema = buildSchema('type Query { hello: String, f(a: String, b: String): String }');
for (const n of [1000, 2000, 4000]) {
  const doc = parse('{ ' + 'hello '.repeat(n) + '}');
  const t = Date.now();
  const errs = validate(schema, doc, [OverlappingFieldsCanBeMergedRule]);
  console.log(n, 'fields', Date.now() - t, 'ms', errs.length);
}
const d2 = parse('{ f(a: "x", b: """y""") f(b: "y", a: "x") }');
console.log(validate(schema, d2, [OverlappingFieldsCanBeMergedRule]).map(e=>e.message));
EOF
node $W/bench.js; git stash list >/dev/null; git status --short | head

W=/home/t3/rq-f52/2026-11-13-claude-builtin-fable-5-2-high/att-032/clone-work && C=$(pwd) && git show main:src/validation/rules/OverlappingFieldsCanBeMergedRule.ts | sed "s#'\.\./\.\./#'$C/src/#g; s#'\.\./ValidationContext'#'$C/src/validation/ValidationContext'#" > $W/BaseRule.ts && cat > $W/bench2.js <<'EOF'
require(process.cwd() + '/resources/ts-register.js');
const { parse } = require(process.cwd() + '/src/language/parser');
const { buildSchema } = require(process.cwd() + '/src/utilities/buildASTSchema');
const { validate } = require(process.cwd() + '/src/validation/validate');
const head = require(process.cwd() + '/src/validation/rules/OverlappingFieldsCanBeMergedRule').OverlappingFieldsCanBeMergedRule;
const base = require(__dirname + '/BaseRule.ts').OverlappingFieldsCanBeMergedRule;
const schema = buildSchema('type Query { hello: String, f(a: String, b: String): String }');
for (const n of [200, 400]) {
  const doc = parse('{ ' + 'hello '.repeat(n) + '}');
  for (const [name, rule] of [['base', base], ['head', head]]) {
    const t = Date.now();
    const errs = validate(schema, doc, [rule]);
    console.log(n, name, Date.now() - t, 'ms', errs.length);
  }
}
for (const q of ['{ f(a: "x", b: """y""") f(b: "y", a: "x") }', '{ f(a: "x", a: "x") f(a: "x", b: "y") }', '{ f(a: "x", b: "y") f(a: "x", a: "x") }']) {
  const d2 = parse(q);
  console.log(q, 'base', validate(schema, d2, [base]).length, 'head', validate(schema, d2, [head]).length);
}
EOF
timeout 280 node $W/bench2.js 2>&1 | grep -v -i "browserslist\|caniuse\|regularly"; git status --short | head

